from pathlib import Path
base=Path('/mnt/data/fresh_destination_complete_design')
logo='assets/logo.jpg'
NAV='''<header class="nav"><a class="logo" href="index.html"><img src="{logo}"></a><nav class="navlinks"><a href="index.html">Home</a><a href="australia.html">Australia</a><a href="japan.html">Japan</a><a href="korea.html">Korea</a><a href="airport-transfer.html">Airport Transfer</a><a href="chauffeur.html">Chauffeur</a><a href="about.html">About</a><a href="contact.html">Contact</a></nav><a class="btn" href="airport-transfer.html">Book Now →</a></header>'''.format(logo=logo)
FOOT='''<footer class="footer"><div class="footergrid"><div><img src="assets/logo.jpg" style="height:62px;background:#fff;border-radius:10px;padding:4px"><p>Private airport transfers and chauffeur services in Australia, Japan and South Korea.</p></div><div><b>Destinations</b><p>Sydney<br>Melbourne<br>Tokyo<br>Osaka<br>Seoul<br>Busan<br>Jeju</p></div><div><b>Services</b><p>Airport Transfer<br>Chauffeur by Day<br>Private Vehicle</p></div><div><b>Policies</b><p><a href="terms.html">Terms & Conditions</a><br><a href="cancellation.html">Cancellation Policy</a></p></div></div></footer>'''
def page(title,body):
    return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} - Fresh Destination</title><link rel="stylesheet" href="styles.css"></head><body><div class="site">{NAV}{body}{FOOT}</div></body></html>'''

def hero(title,sub,img): return f'''<section class="hero desktop-short" style="background-image:url('{img}')"><div class="hero-content"><div class="eyebrow">Fresh Destination</div><h1>{title}</h1><p>{sub}</p></div></section>'''

def dest_card(name,cities,img,href): return f'''<a class="card" href="{href}"><div class="photo" style="background-image:url('{img}')"></div><div class="pad"><h3>{name}</h3><p>{cities}</p><span class="pill">Explore destination →</span></div></a>'''

home=hero('Your Private Driver,<br>Wherever You Travel','Airport transfers or a chauffeur by the day across Australia, Japan and South Korea.','assets/sydney.jpg')+'''<div class="wrap"><div class="searchbox"><div class="field"><label>Country</label><select class="select"><option>Select country</option><option>Australia</option><option>Japan</option><option>South Korea</option></select></div><div class="field"><label>City</label><select class="select"><option>Select city</option></select></div><div class="field"><label>Date</label><input class="input" value="Select date"></div><div class="field"><label>Passengers</label><select class="select"><option>1 passenger</option></select></div><a class="btn" href="airport-transfer.html">Get Quote →</a></div><div class="features"><div class="feature"><div class="icon">✓</div><div><b>Reliable Drivers</b><div class="small">Professional local partners</div></div></div><div class="feature"><div class="icon">🚙</div><div><b>Comfortable Vehicles</b><div class="small">Well-maintained vehicles</div></div></div><div class="feature"><div class="icon">▣</div><div><b>Easy Booking</b><div class="small">Simple online process</div></div></div><div class="feature"><div class="icon">★</div><div><b>Trusted by Travellers</b><div class="small">Families and business travellers</div></div></div></div><div class="spacer"></div><div class="section-title"><div class="eyebrow">Our destinations</div><h2>Choose Your Destination</h2><p>Currently available in selected cities.</p></div><div class="grid three">'''+dest_card('Australia','Sydney • Melbourne','assets/sydney.jpg','australia.html')+dest_card('Japan','Tokyo • Osaka','assets/japan.jpg','japan.html')+dest_card('South Korea','Seoul • Busan • Jeju','assets/korea.jpg','korea.html')+'''</div><div class="spacer"></div><div class="section-title"><div class="eyebrow">Our services</div><h2>Two simple ways to travel</h2></div><div class="grid two"><div class="card"><div class="photo" style="background-image:url('assets/airport.jpg')"></div><div class="pad"><h3>Airport Transfer</h3><p>Private airport pickup or drop-off with fixed pricing and coordinated pickup.</p><a class="btn ghost" href="airport-transfer.html">Book Airport Transfer →</a></div></div><div class="card"><div class="photo" style="background-image:url('assets/chauffeur.jpg')"></div><div class="pad"><h3>Chauffeur by Day</h3><p>Your private vehicle and professional driver for the day with a flexible itinerary.</p><a class="btn ghost" href="chauffeur.html">Book Chauffeur →</a></div></div></div></div>'''
(base/'index.html').write_text(page('Home',home))

# Destination pages
def destpage(country,cities,img,uses):
    tabs=''.join([f'<div class="tab {"active" if i==0 else ""}">{c}</div>' for i,c in enumerate(cities)])
    usecards=''.join([f'<div class="card"><div class="photo" style="background-image:url(\'{img}\')"></div><div class="pad"><b>{u}</b></div></div>' for u in uses])
    body=hero(country,f'Private chauffeur services in {", ".join(cities)}. Airport transfers or a chauffeur by the day.',img)+f'''<div class="wrap"><div class="tabs">{tabs}</div><div class="spacer"></div><div class="section-title"><h2>Popular Uses</h2></div><div class="grid four">{usecards}</div><div class="spacer"></div><div class="grid two"><div class="card pad"><h3>Airport Transfer</h3><p>Reliable airport pickup and drop-off with simple fixed pricing.</p><a class="btn" href="airport-transfer.html">Book Airport Transfer →</a></div><div class="card pad"><h3>Chauffeur by Day</h3><p>Flexible daily service for sightseeing, shopping, family trips or business.</p><a class="btn" href="chauffeur.html">Book Chauffeur →</a></div></div></div>'''
    return body
(base/'australia.html').write_text(page('Australia',destpage('Australia',['Sydney','Melbourne'],'assets/sydney.jpg',['Airport Transfer','City Tour','Blue Mountains','Business Travel'])))
(base/'japan.html').write_text(page('Japan',destpage('Japan',['Tokyo','Osaka'],'assets/japan.jpg',['Airport Transfer','Mt. Fuji Day Trip','City Tour','Shopping'])))
(base/'korea.html').write_text(page('South Korea',destpage('South Korea',['Seoul','Busan','Jeju'],'assets/korea.jpg',['Airport Transfer','City Tour','Shopping','Island Tour'])))

