(base/'airport-transfer.html').write_text(page('Airport Transfer',airt))

chau=hero('Chauffeur by Day','Your private vehicle, professional driver and flexible itinerary.','assets/japan.jpg')+f'''<div class="wrap">{steps(0)}<div class="form-card"><div class="form-grid four"><div class="field"><label>City</label><select class="select"><option>Tokyo</option><option>Sydney</option><option>Melbourne</option><option>Osaka</option><option>Seoul</option><option>Busan</option><option>Jeju</option></select></div><div class="field"><label>Date</label><input class="input" value="Select date"></div><div class="field"><label>Service Hours</label><select class="select"><option>8 hours</option><option>10 hours</option></select></div><div class="field"><label>Passengers</label><select class="select"><option>1 passenger</option><option>2 passengers</option><option>3 passengers</option></select></div></div><div class="spacer"></div><div class="field"><label>Your Itinerary (Optional)</label><textarea class="textarea" placeholder="Places you want to visit"></textarea></div><div class="spacer"></div><a class="btn" style="width:100%" href="vehicle.html">Search Vehicles →</a></div></div>'''
